__NUXT_JSONP__("/inclusion/publicaciones/manifiesto_unidas_por_el_trabajo_justo_y_la_dignidad_laboral_de_las_mujeres", (function(a,b,c,d,e,f,g,h,i,j,k,l){return {data:[{post:{slug:"manifiesto_unidas_por_el_trabajo_justo_y_la_dignidad_laboral_de_las_mujeres",title:"Manifiesto UNIDAS: Por el trabajo justo y la dignidad laboral de las mujeres",date:"2025-03-25T22:22:20.616Z",img:"https:\u002F\u002Fucarecdn.com\u002F87db4246-801e-4855-8c38-3bad4d313636\u002F","img-alt":"UNIDAS Red de mujeres por el trabajo justo",autor:"Ethos, Fundación Avina, ProDESC y Oxfam México",category:c,extracto:"En México, más de la mitad de la población trabaja en la economía informal. Esto implica una situación de desprotección social y falta de acceso a derechos, especialmente para las mujeres que se encuentran en mayor vulnerabilidad. Por eso lanzamos UNIDAS: Red de mujeres por el trabajo justo, un esfuerzo colectivo que nace de la necesidad urgente de transformar la realidad laboral de miles de mujeres en nuestro país. ",file:"https:\u002F\u002Fucarecdn.com\u002F7dbc97bc-5d23-4c46-8914-e7d0f24641c7\u002F",toc:[],body:{type:d,children:[{type:b,tag:e,props:{},children:[{type:a,value:"En México, más de la mitad de la población trabaja en la economía informal. Esto implica una situación de desprotección social y falta de acceso a derechos, especialmente para las mujeres que se encuentran en mayor vulnerabilidad. Por eso lanzamos UNIDAS: Red de mujeres por el trabajo justo, un esfuerzo colectivo que nace de la necesidad urgente de transformar la realidad laboral de miles de mujeres en nuestro país."}]}]},dir:f,path:"\u002Fpublicaciones\u002Fmanifiesto_unidas_por_el_trabajo_justo_y_la_dignidad_laboral_de_las_mujeres",extension:g,createdAt:h,updatedAt:h},publicaciones:[{slug:"cuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",title:"Cuidados para la primera infancia: Recomendaciones hacia la conformación del Sistema Nacional de Cuidados",date:"2025-03-18T14:41:00.000Z",img:"https:\u002F\u002Fucarecdn.com\u002Ffca2a0ef-b4dd-4e5f-9a7f-c17d24f27d70\u002F-\u002Fcrop\u002F1047x1377\u002F18,15\u002F-\u002Fpreview\u002F","img-alt":"Cuidados para la primera infancia",autor:"Ethos, Early Institute y el Centro de Investigación Económica y Presupuestaria ",category:c,extracto:"En este documento, se analiza el panorama actual del cuidado y se visibiliza su relevancia para la primera infancia, con el fin de generar recomendaciones para la creación, diseño, implementación y monitoreo de un Sistema Nacional de Cuidados con perspectiva de niñez. ",file:"https:\u002F\u002Fucarecdn.com\u002Fb2c423fb-64a1-42e7-9f85-07fff85a84e8\u002F",toc:[],body:{type:d,children:[{type:b,tag:e,props:{},children:[{type:a,value:"En este documento, se analiza el panorama actual del cuidado y se visibiliza su relevancia para la primera infancia, con el fin de generar recomendaciones para la creación, diseño, implementación y monitoreo de un Sistema Nacional de Cuidados con perspectiva de niñez."}]}]},dir:f,path:"\u002Fpublicaciones\u002Fcuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",extension:g,createdAt:i,updatedAt:i},{slug:"el_seguro_popular_de_salud_en_mexico_posibles_efectos_sobre_la_economia_informal",title:"El Seguro Popular de salud en México: posibles efectos sobre la economía informal",date:"2011-02-01T15:47:13.927Z",img:"https:\u002F\u002Fucarecdn.com\u002F9fad819f-509d-482c-a742-2390b145e21a\u002F",autor:"Alicia Santana Cartas, Liliana Alvarado Baena, Stephen Birtwistle y Carlos Demian Rivera Saldaña",category:c,extracto:"La economía informal es un fenómeno en la historia de México que ha adquirido importancia en las últimas décadas. Consecuencia de ello es la preocupación de ciertos sectores de la sociedad por aminorar su peso dentro de la economía.",file:"https:\u002F\u002Fucarecdn.com\u002Fb6bdcf0a-3d62-4d08-b4fc-be722d29eec3\u002F",toc:[],body:{type:d,children:[{type:a,value:j},{type:b,tag:e,props:{},children:[{type:a,value:"La economía informal es un fenómeno en la historia de México que ha adquirido importancia en las últimas décadas. Consecuencia de ello es la preocupación de ciertos sectores de la sociedad por aminorar su peso dentro de la economía. Los estudios que analizan a la informalidad coinciden en que el desempeño económico, las cargas tributarias, las excesivas regulaciones, así como el bajo capital humano de los trabajadores, son los principales factores que causan y fomentan la informalidad. Por su parte, la evasión de impuestos, el incumplimiento de la regulación gubernamental y una baja productividad, han sido identificados como sus principales resultados. En este documento se desarrolla a profundidad la relación que guarda la informalidad con el Seguro Popular (SP). Lo anterior, debido a la trascendencia que tiene este tema en distintos rubros como son las finanzas públicas y la salud"}]},{type:a,value:j}]},dir:f,path:"\u002Fpublicaciones\u002Fel_seguro_popular_de_salud_en_mexico_posibles_efectos_sobre_la_economia_informal",extension:g,createdAt:"2023-06-19T05:12:04.602Z",updatedAt:"2022-08-28T23:28:14.353Z"},{slug:"evidence_for_integrating_the_gender_perspective_into_comprehensive_disaster_risk_management_in_mexico",title:"Evidence for Integrating the Gender Perspective into Comprehensive Disaster Risk Management in Mexico",date:"2025-10-14T17:05:58.063Z",img:"https:\u002F\u002Fucarecdn.com\u002F9a378ae9-4b9c-448a-9ed4-0878a22bb795\u002F","img-alt":"Disaster risk management",autor:"Ethos",category:c,extracto:"Disasters in Mexico are not only environmental but also deeply social. Their impacts are magnified by structural inequalities – poverty, gender-based violence, and unequal access to resources. Women, in particular, face disproportionate risks: 70.1% of Mexican women aged 15 and older have experienced violence, and their labor force participation rate (46%) remains far below that of men (76.3%). These structural inequalities heighten vulnerability before, during, and after disasters, exacerbating physical, social, and economic insecurity.",file:"https:\u002F\u002Fucarecdn.com\u002F4ac134d0-a697-4f3c-9dbd-e1c6b0107f36\u002F",toc:[],body:{type:d,children:[{type:b,tag:e,props:{},children:[{type:a,value:"Disasters in Mexico are not only environmental but also "},{type:b,tag:k,props:{},children:[{type:a,value:"deeply social"}]},{type:a,value:". Their impacts are magnified by structural inequalities – poverty, gender-based violence, and unequal access to resources. Women, in particular, face "},{type:b,tag:k,props:{},children:[{type:a,value:"disproportionate risks"}]},{type:a,value:": 70.1% of Mexican women aged 15 and older have experienced violence, and their labor force participation rate (46%) remains far below that of men (76.3%). These structural inequalities heighten vulnerability before, during, and after disasters, exacerbating physical, social, and economic insecurity."}]}]},dir:f,path:"\u002Fpublicaciones\u002Fevidence_for_integrating_the_gender_perspective_into_comprehensive_disaster_risk_management_in_mexico",extension:g,createdAt:l,updatedAt:l}]}],fetch:{},mutations:[]}}("text","element","inclusion","root","p","\u002Fpublicaciones",".md","2025-04-23T06:21:15.399Z","2025-04-23T06:21:15.398Z","\n","strong","2025-11-25T01:24:03.288Z")));